import { boardLengthLimits, boardWidthLimits, configuredWidth, extrasPrice, isShelf, configurationError, categories, demoProducts, defaultProcessing, initialConfig, priceDetails, money, details, shipping, typeNames, type Product, type Processing, type Configuration, type CartItem } from '@/lib/catalog';

function displayImage(src:string){return src==='/images/shelf.webp'?'/images/quiet-shelf.webp':src==='/images/board.webp'||src==='/images/hero.webp'?'/images/quiet-hero.webp':src;}
interface Store {products:Product[];processing:Processing;cart:CartItem[];favorites:string[];loading:boolean;error:string;add:(p:Product,c:Configuration,quantity?:number)=>boolean;quantity:(key:string,n:number)=>void;remove:(key:string)=>void;clear:()=>void;favorite:(id:string)=>void;reload:()=>Promise<void>;toast:(s:string)=>void;}
const StoreContext=createContext<Store>(null!);
export const useStore=()=>useContext(StoreContext);
export function StoreProvider({children}:{children:ReactNode}){
 const [products,setProducts]=useState<Product[]>(demoProducts),[processing,setProcessing]=useState(defaultProcessing),[cart,setCart]=useState<CartItem[]>([]),[favorites,setFavorites]=useState<string[]>([]),[ready,setReady]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[message,setMessage]=useState('');const timer=useRef<ReturnType<typeof setTimeout>|null>(null);
 const toast=(s:string)=>{setMessage(s);if(timer.current)clearTimeout(timer.current);timer.current=setTimeout(()=>setMessage(''),4500);};
 async function reload(){setError('');try{const res=await fetch('/api/catalog',{cache:'no-store'});if(!res.ok)throw new Error();const data=await res.json() as {products:Product[];processing:Processing};setProducts(data.products);setProcessing(data.processing);}catch{setError('Не удалось обновить наличие. Показаны демонстрационные данные.');}finally{setLoading(false);}}
 useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem('kelo-cart-v1')||'[]');if(Array.isArray(saved)){let changed=false;const restored=saved.filter(i=>i?.product?.id&&i?.config?.length&&i?.quantity>0).map((i:CartItem)=>{const product=i.product,defaults=initialConfig(product),mode=product.category==='slabs'?'board':'product';const length=mode==='board'?Math.max(boardLengthLimits.minCm,Math.min(boardLengthLimits.maxCm,Math.round(i.config.length))):product.maxLength;if(length!==i.config.length)changed=true;const config={...defaults,...i.config,mode:mode as 'board'|'product',length,type:defaults.type,width:mode==='board'?Math.min(boardWidthLimits.maxCm,product.width,i.config.width||product.width):product.width,supports:isShelf(product)&&!!i.config.supports,giftWrap:!!i.config.giftWrap};return {...i,config,key:JSON.stringify(config),quantity:Math.min(20,i.quantity)};});setCart(restored);if(changed)toast('Размеры в сохранённой корзине обновлены по новым параметрам заказа. Проверьте их перед оформлением.');};const fav=JSON.parse(localStorage.getItem('kelo-favorites')||'[]');if(Array.isArray(fav))setFavorites(fav);}catch{}setReady(true);void reload();return()=>{if(timer.current)clearTimeout(timer.current);};},[]);
 useEffect(()=>{if(ready){try{localStorage.setItem('kelo-cart-v1',JSON.stringify(cart));localStorage.setItem('kelo-favorites',JSON.stringify(favorites));}catch{}}},[cart,favorites,ready]);
 const add=(p:Product,c:Configuration,n=1)=>{const invalid=configurationError(p,c);if(invalid){toast(invalid);return false;}const key=JSON.stringify(c);const consumed=cart.filter(i=>i.product.id===p.id).reduce((s,i)=>s+i.config.length*i.quantity,0);const previous=cart.find(i=>i.key===key)?.quantity||0;if(!Number.isInteger(n)||n<1||previous+n>20){toast('Не более 20 изделий в одной позиции');return false;}if(consumed+c.length*n>p.remainingCm){toast('Недостаточно материала. Уменьшите количество.');return false;}setCart(prev=>{const found=prev.find(i=>i.key===key);if(found)return prev.map(i=>i.key===key?{...i,quantity:i.quantity+n}:i);return [...prev,{key,product:p,config:{...c},quantity:n,price:priceDetails(p,c,processing).total}];});toast('Изделие добавлено в корзину');return true;};
 const quantity=(key:string,n:number)=>{if(n<1||n>20)return;const item=cart.find(i=>i.key===key);if(!item)return;const p=products.find(p=>p.id===item.product.id)||item.product;const consumed=cart.filter(i=>i.key!==key&&i.product.id===p.id).reduce((s,i)=>s+i.quantity*i.config.length,0);if(consumed+item.config.length*n>p.remainingCm){toast('На этой доске больше нет свободного материала');return;}setCart(c=>c.map(i=>i.key===key?{...i,quantity:n}:i));};
 return <StoreContext.Provider value={{products,processing,cart,favorites,loading,error,add,quantity,remove:key=>setCart(c=>c.filter(i=>i.key!==key)),clear:()=>setCart([]),favorite:id=>setFavorites(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]),reload,toast}}><InteractiveSurface>{children}<motion.div className={'toast '+(message?'visible':'')} role="status" initial={false} animate={{opacity:message?1:0,y:message?0:14}} style={{x:'-50%'}} transition={{duration:.22}}><CheckCircle2 size={19}/>{message}{message.includes('добавлено')&&<a href="/cart">В корзину </a>}</motion.div></InteractiveSurface></StoreContext.Provider>;
}
