function MaterialGallery(){
 const [selected,setSelected]=useState(0);const reduced=useReducedMotion(),tabsId=useId();
 const slides=[{label:'Фактура',image:'gallery/home-grain',title:<>Рисунок, который<br/>невозможно повторить.</>,text:'Сучки, трещины и серебристая текстура. Всё, за что мы любим Кело.',alt:'Макрофотография природного сучка и волокон сосны Кело'},{label:'Живой край',image:'gallery/home-edge',title:<>Природа задала форму.<br/>Мы её сохранили.</>,text:'Неровный край остаётся частью изделия. Длину и обработку выбираете вы.',alt:'Цельный слэб Кело с естественными неровными краями на чёрном фоне'},{label:'В интерьере',image:'gallery/home-shelf',title:<>Маленькая деталь.<br/>Другое ощущение дома.</>,text:'Полка из массива — место для любимых вещей и природный акцент в интерьере.',alt:'Полка из натуральной древесины Кело на тёмной стене'}];
 return <section className="gallery-highlights section" id="highlights"><div className="container"><div className="gallery-section-heading"><p className="eyebrow">Ближе к природе</p><h2>Характер. В деталях.</h2></div><div className="gallery-frame" aria-live="polite" aria-atomic="true"><AnimatePresence initial={false}><motion.img initial={{opacity:0,x:reduced?0:24}} animate={{opacity:1,x:0}} exit={{opacity:0,x:reduced?0:-24}} transition={{duration:.35}} className="gallery-slide-image" key={selected} src={'/images/'+slides[selected].image+'.webp'} alt={slides[selected].alt} loading="lazy"/></AnimatePresence><motion.div key={selected+'-copy'} initial={{opacity:0,y:reduced?0:12}} animate={{opacity:1,y:0}} transition={{duration:.3,delay:.08}} className="gallery-slide-copy"><h3>{slides[selected].title}</h3><p>{slides[selected].text}</p></motion.div></div><div className="gallery-pagination"><div className="gallery-selector" role="group" aria-label="Детали древесины">{slides.map((s,i)=><button type="button" key={s.label} className={selected===i?'active':''} aria-pressed={selected===i} onClick={()=>setSelected(i)}>{selected===i&&<motion.span className="gallery-tab-indicator" layoutId={tabsId} transition={{type:'spring',stiffness:440,damping:35}}/>}<span>{s.label}</span></button>)}</div><span className="gallery-slide-count" aria-hidden="true">0{selected+1} / 03</span></div><p className="fine-print gallery-image-note">Демонстрационные изображения. Рисунок каждой реальной доски уникален.</p></div></section>;
}
export function HomePage(){
 const {products}=useStore();const rate=Math.min(...products.filter(p=>p.active&&p.category==='slabs').map(p=>p.rate));
 return <main id="main" className="gallery-home"><section className="gallery-hero"><div className="container"><p className="gallery-product-label">Слэбы Кело.</p><div className="gallery-hero-stage"><img className="gallery-hero-image" src={editorialImages.hero} alt="Слэб карельской сосны Кело: натуральный рисунок, сучки и живой край" fetchPriority="high" width="1536" height="1024"/></div><div className="gallery-hero-copy"><h1>Натуральное дерево<br/><span>с характером.</span></h1><p>Уникальные слэбы карельской сосны Кело.<br/>Природная красота. В вашем размере.</p><div className="gallery-purchase"><span className="gallery-price">От {money(Number.isFinite(rate)?rate:2400)} / пог. м <small>Демо-цена</small></span><a className="btn" href="/constructor">Заказать</a></div></div></div></section>
 <MaterialGallery/>
 <BoardOrderBlock/>
 <section className="section gallery-material" id="about"><div className="container"><div className="gallery-material-heading"><p className="eyebrow">Карельская сухостойная сосна</p><h2>У дерева есть характер.<br/><span>Мы его сохраняем.</span></h2><p>Кело — северная сосна, высохшая естественным образом. Её фактура, сучки и трещины становятся частью вашего интерьера. Мы бережно готовим материал к новой истории.</p></div><div className="gallery-material-grid"><article><img src={editorialImages.materialEdge} alt="Естественный рисунок древесных волокон и сучков" loading="lazy"/><h3>Живой край.</h3><p>Природный силуэт вместо одинаковых линий.</p></article><article><img src={editorialImages.thickness} alt="Заготовки из массива сосны Кело" loading="lazy"/><h3>30 или 40 мм.</h3><p>Две толщины для разных идей и задач.</p></article><article><img src={editorialImages.long} alt="Длинная цельная доска с естественным краем" loading="lazy"/><h3>До 6 метров.</h3><p>Исходные доски на складе. Для заказа выберите длину до 150 см.</p></article></div><div className="gallery-karelia"><img src="/images/forest.webp" alt="Сосновый лес Карелии на скалистом берегу озера — атмосферная иллюстрация" loading="lazy"/><div><p className="eyebrow">Родом с севера</p><h3>Спокойствие леса.<br/>Тепло настоящего дерева.</h3><p>Карелия — наше вдохновение. Натуральная древесина — материал, с которым хочется жить.</p></div></div></div></section>
 <section className="section container project-examples" id="ideas"><SectionTitle eyebrow="Идеи для вашего дома" title={<>Что можно создать<br/>из Кело.</>}/><div className="project-examples-grid">{projectExamples.map(project=><article className="project-example" key={project.title}><img src={project.image} alt={project.title+' из натуральной древесины — визуализация'} loading="lazy" width="1536" height="1024"/><div><h3>{project.title}</h3><p>{project.description}</p><a className="project-example-link" href={project.href}>{project.action}</a></div></article>)}</div><p className="fine-print">Примеры для вдохновения. Мы предлагаем древесину и заготовки; опоры и крепёж подбираются отдельно.</p></section>
 <section className="steps-section section container"><SectionTitle eyebrow="От выбора до дома" title="Всё начинается с доски."/><div className="steps-grid">{[['01','Познакомьтесь с Кело','Рассмотрите фактуру и живой край доски.'],['02','Задайте параметры','Настройте длину и обработку. Цена появится сразу.'],['03','Оформите заказ','Укажите контакты и выберите доставку.'],['04','Создайте своё','Мы подготовим и бережно упакуем изделие.']].map(([num,title,text])=><div className="step" key={num}><span>{num}</span><h3>{title}</h3><p>{text}</p></div>)}</div></section>
 <section className="delivery-section section" id="delivery"><div className="container delivery-grid"><div><p className="eyebrow">Доставка и оплата</p><h2>Продумано.<br/>До вашего порога.</h2><p className="section-description">Размер и обработка — в конструкторе.<br/>Доставка — с учётом вашего изделия.</p><a className="text-link" href="/constructor">Рассчитать изделие</a></div><div className="faq-list">{[['Доставка по России','Способ и сроки согласуем перед отправкой. Для изделий до 250 см в оформлении показан пример расчёта. Яндекс Доставка пока не подключена.'],['Длинные доски','Для изделий длиннее 250 см доставку рассчитаем индивидуально. До согласования она не включается в итоговую сумму.'],['Оплата заказа','ЮKassa пока не подключена. Оформление и онлайн-оплата работают в демонстрационном режиме: деньги не списываются, данные карты не запрашиваются.'],['Самовывоз','Без стоимости доставки. Адрес склада и сроки подготовки уточняются при согласовании заказа.']].map(([title,text],i)=><details key={title} open={i===0}><summary>{title}<Plus size={19}/></summary><p>{text}</p></details>)}</div></div></section>
 <section className="section container closing-section" id="contacts"><p className="eyebrow">KELO WOOD MARKET</p><h2>Природа создала.<br/>Продолжите вы.</h2><p>Натуральная доска Кело для интерьера с характером.<br/>Задайте свой размер — и начните новую историю.</p><a className="btn" href="/constructor">Заказать</a><DemoNote/></section></main>;
}
export function BoardOrderBlock(){return <section className="section container board-order-section" id="board" aria-labelledby="board-order-title"><article className="board-order-card"><div className="board-order-media"><img src="/images/gallery/slabs-angle.webp" alt="Натуральная доска сосны Кело с живым краем и выразительной текстурой — пример" loading="lazy" width="1536" height="1024"/></div><div className="board-order-copy"><p className="eyebrow">Природа. В вашем размере.</p><h2 id="board-order-title">Доска Кело.</h2><p className="board-order-description">Карельская сухостойная сосна с живым краем, серебристой фактурой и неповторимым рисунком. Сохраним её характер и подготовим под вашу идею.</p><dl className="board-order-specs"><div><dt>Длина</dt><dd>30–150 см</dd></div><div><dt>Ширина</dt><dd>до 400 мм</dd></div><div><dt>Толщина</dt><dd>30 / 40 мм</dd></div></dl><a className="btn board-order-button" href="/constructor">Заказать</a><p className="board-order-helper">Размеры, обработку и количество выберете в редакторе.</p><p className="fine-print board-order-demo">Изображение — пример материала. Стоимость рассчитывается в редакторе.</p></div></article></section>;}
export function ProductCard({p}:{p:Product}){const {favorites,favorite}=useStore();const available=p.remainingCm>=(p.category==='slabs'?boardLengthLimits.minCm:p.maxLength);return <article className={'product-card '+(!available?'unavailable':'')}><PhotoGallery photos={productPhotoSet(p)} label={p.name} variant="product" href={'/product/'+p.id}><span className="product-badge">{available?<><i/>В наличии · демо</>:'Нет в наличии'}</span><button className={'favorite '+(favorites.includes(p.id)?'selected':'')} type="button" aria-label={(favorites.includes(p.id)?'Убрать из избранного ':'В избранное ')+p.name} aria-pressed={favorites.includes(p.id)} onClick={()=>favorite(p.id)}><Heart size={19}/></button></PhotoGallery><div className="product-info"><div className="product-overline"><span>КАРЕЛЬСКАЯ СОСНА</span><span>{p.id}</span></div><h3><a href={'/product/'+p.id}>{p.name}</a></h3><p className="product-dimensions">До {Math.min(p.maxLength,p.remainingCm)} × {p.width} см <span/> {p.thickness} мм</p><div className="product-bottom"><span>от <b>{money(p.rate)}</b><small> / пог. м</small></span><a className="product-go" href={'/constructor?board='+p.id} aria-label={'Настроить '+p.name}>Заказать</a></div></div></article>;}
export function Footer(){const [legal,setLegal]=useState(false);return <footer className="footer"><div className="container"><div className="footer-main"><div className="footer-brand"><Brand/><p>У дерева есть характер.<br/>Мы его сохраняем.</p><span>НАТУРАЛЬНО. НЕПОВТОРИМО. КЕЛО.</span></div><div><h3>О доске</h3><a href="/#board">Доска Кело</a><a href="/#highlights">Фактура и живой край</a><a href="/#about">О материале</a><a href="/#ideas">Идеи для дома</a></div><div><h3>Покупателям</h3><a href="/constructor">Конструктор в размер</a><a href="/#delivery">Доставка и оплата</a><a href="/#about">О древесине Кело</a><a href="/cart">Корзина</a></div><div className="footer-contact"><h3>Ваша история с Кело</h3><p>Начните с красивой доски.<br/>Остальное создадим вместе.</p><a className="text-link light-link" href="/constructor">Заказать доску</a><small>kelowoodmarket.ru · Карелия</small></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} KELO WOOD MARKET</span><button onClick={()=>setLegal(true)}>Обработка данных</button><a href="/admin">Панель управления </a><span>Создано с уважением к природе</span></div></div>{legal&&<Modal title="Обработка данных в демо-версии" onClose={()=>setLegal(false)}><div className="prose"><p>Это закрытая демонстрационная версия магазина. При оформлении сохраняются имя, телефон, электронная почта, адрес, комментарий и состав заказа. Они доступны владельцу сайта в панели управления и используются для проверки работы заказа.</p><p>Данные банковской карты не запрашиваются. ЮKassa и Яндекс Доставка не подключены, данные этим сервисам не передаются.</p><p>Перед запуском продаж владелец должен добавить реквизиты оператора, контакты для запросов об удалении данных, сроки хранения и окончательную политику. Для проверки формы используйте вымышленные контактные данные.</p></div></Modal>}</footer>;}
export function CatalogPage(){return <main id="main" className="board-page"><div className="container"><Breadcrumb current="Доска Кело"/><div className="page-title"><p className="eyebrow">KELO WOOD MARKET</p><h1>Одна доска.<br/>Много возможностей.</h1><p>Натуральный материал для вашей идеи. Размеры и обработка — в отдельном редакторе.</p></div></div><BoardOrderBlock/></main>;}
export function Breadcrumb({current}:{current:string}){return <nav className="breadcrumb" aria-label="Хлебные крошки"><a href="/">Главная</a><span aria-hidden="true">/</span>{!['Каталог','Доска Кело'].includes(current)&&<><a href="/catalog">Доска Кело</a><span aria-hidden="true">/</span></>}<span>{current}</span></nav>;}
function Empty({icon,title,text,children}:{icon:ReactNode;title:string;text:string;children?:ReactNode}){return <div className="empty-state">{icon}<h2>{title}</h2><p>{text}</p>{children}</div>;}
export function BoardPreview({p,c}:{p:Product;c:Configuration}){
 const uid=useId().replace(/:/g,'');const mesh=createBoardMesh(p,c),scale=Math.min(620/mesh.length,220/mesh.width),cx=375,cy=190;const map=(v:number[])=>[cx+v[0]*scale,cy+v[1]*scale];const path=(ring:number[][])=>ring.map((v,i)=>{const a=map(v);return (i?'L':'M')+a[0]+','+a[1];}).join(' ')+' Z';const shape=[path(mesh.outline),...mesh.holes.map(path)].join(' ');const left=cx-mesh.length*scale/2,right=cx+mesh.length*scale/2,top=cy-mesh.width*scale/2,bottom=cy+mesh.width*scale/2;
 return <svg className="board-preview" viewBox="0 0 800 370" role="img" aria-label={`Схема: ${c.length} на ${configuredWidth(p,c)} сантиметров, толщина ${c.thickness} миллиметров, ${c.holes} отверстий`}><defs><clipPath id={'board-clip-'+uid}><path d={shape} fillRule="evenodd" clipRule="evenodd"/></clipPath></defs><path d={shape} transform="translate(0 5)" fill="#7c6750" fillRule="evenodd"/><path d={shape} fill="#c8ad88" fillRule="evenodd"/><image href="/images/board.webp" x={cx-(bottom-top)*6.3*.75} y={top-(bottom-top)*2.8} width={(bottom-top)*6.3*1.5} height={(bottom-top)*6.3} preserveAspectRatio="none" clipPath={`url(#board-clip-${uid})`}/><g stroke="#86868b" strokeWidth="1" fill="none"><path d={`M${left},${top-24}H${right}M${left},${top-30}V${top-18}M${right},${top-30}V${top-18}`}/><path d={`M${right+28},${top}V${bottom}M${right+22},${top}H${right+34}M${right+22},${bottom}H${right+34}`}/></g><text x={cx} y={top-40} textAnchor="middle">{c.length} см</text><text x={right+43} y={cy+5}>{configuredWidth(p,c)} см</text><text x={cx} y="345" textAnchor="middle" className="board-caption">{c.cut?'ПРЯМОЙ СПИЛ · '+(c.side==='left'?'ЛЕВАЯ':'ПРАВАЯ')+' СТОРОНА':'ЖИВОЙ КРАЙ · ОБЕ СТОРОНЫ'}{c.holes?' / '+c.holes+' ОТВЕРСТИЯ':''}</text></svg>;
}
export function Configurator({compact=false,initialId}:{compact?:boolean;initialId?:string}){
 const {products,processing,add,toast}=useStore();const [c,setC]=useState<Configuration>(initialConfig(demoProducts.find(p=>p.category==='slabs'&&p.thickness===40&&p.width>=40)||demoProducts[0])),[added,setAdded]=useState(false),[lengthDraft,setLengthDraft]=useState('120'),[count,setCount]=useState(1),[productCategory,setProductCategory]=useState('shelves');
 const p=products.find(p=>p.id===c.productId)||demoProducts[0],mode=c.mode||'board',boardMode=mode==='board',boardWidth=configuredWidth(p,c);const boards=products.filter(p=>p.active&&p.category==='slabs'&&p.remainingCm>=boardLengthLimits.minCm),goods=products.filter(p=>p.active&&p.category!=='slabs'&&p.remainingCm>=p.maxLength);const maxLength=Math.max(boardLengthLimits.minCm,Math.min(boardLengthLimits.maxCm,p.maxLength,p.remainingCm));const price=priceDetails(p,c,processing);const valid=!!p.active&&!configurationError(p,c)&&p.remainingCm>=c.length*count&&(boardMode||p.category===productCategory);
 useEffect(()=>{const id=initialId||new URLSearchParams(window.location.search).get('board');const found=products.find(x=>x.id===id);if(found){setC(initialConfig(found));setProductCategory(found.category==='slabs'?'shelves':found.category);}},[initialId,products]);
 useEffect(()=>setLengthDraft(String(Math.round(c.length))),[c.length]);
 const update=(next:Partial<Configuration>)=>{setC(old=>({...old,...next}));setAdded(false);};
 const pickBoard=(target:Product,desiredWidth=boardWidth)=>update({productId:target.id,thickness:target.thickness,width:Math.min(boardWidthLimits.maxCm,target.width,desiredWidth),length:Math.max(boardLengthLimits.minCm,Math.min(c.length,boardLengthLimits.maxCm,target.maxLength,target.remainingCm)),mode:'board',type:'slab',supports:false});
 const chooseGood=(target:Product)=>{setC({...initialConfig(target),giftWrap:c.giftWrap});setAdded(false);};
 const switchMode=(next:'board'|'product')=>{if(next===mode)return;const target=next==='board'?(boards.find(x=>x.width>=40&&x.thickness===40)||boards[0]):goods.find(x=>x.category==='shelves')||goods[0];if(!target){toast('В этой категории пока нет доступного материала');return;}setC({...initialConfig(target),giftWrap:c.giftWrap});setProductCategory(target.category==='slabs'?'shelves':target.category);setCount(1);setAdded(false);};
 const changeThickness=(n:number)=>{const found=boards.find(x=>x.thickness===n&&x.width>=boardWidth)||boards.find(x=>x.thickness===n);if(found)pickBoard(found);else toast('В этой толщине пока нет доступных досок');};
 const changeWidth=(millimeters:string)=>{const centimeters=Number(millimeters)/10;const found=boards.find(x=>x.thickness===c.thickness&&x.width>=centimeters);if(found)pickBoard(found,centimeters);else toast('Для этой ширины выберите другую толщину');};
 const setLengthCm=(value:number)=>{const cm=Math.min(maxLength,Math.max(boardLengthLimits.minCm,Math.round(value)));update({length:cm});setLengthDraft(String(cm));};
 const lengthControls = <div className="under-board-controls">{boardMode?<div className="length-under-image"><div className="length-label"><label htmlFor={'length-'+compact}>Длина доски</label><div><input id={'length-number-'+compact} type="number" aria-label="Длина доски в сантиметрах" min={30} max={maxLength} step={1} value={lengthDraft} onChange={e=>{setLengthDraft(e.target.value);const n=Number(e.target.value);if(n>=30&&n<=maxLength&&Number.isInteger(n))update({length:n});}} onBlur={()=>setLengthCm(Number(lengthDraft)||30)}/><span>см</span></div></div><DetentRange id={'length-'+compact} min={30} max={maxLength} value={c.length} onChange={setLengthCm}/><div className="range-labels"><span>30 см</span><span>Максимум {maxLength} см · шаг 1 см</span></div></div>:<div className="fixed-product-size"><span>Размер изделия</span><b>{c.length} × {configuredWidth(p,c)} см · {c.thickness} мм</b></div>}<div className="under-image-options">{boardMode&&<div className="under-image-thickness"><span>Толщина доски</span><div className="segmented" role="group" aria-label="Толщина доски">{[30,40].map(n=><button type="button" key={n} aria-pressed={c.thickness===n} className={c.thickness===n?'active':''} onClick={()=>changeThickness(n)}>{n} мм</button>)}</div></div>}<label className="board-quantity-label">{boardMode?'Количество досок':'Количество изделий'}<input type="number" inputMode="numeric" min={1} max={20} step={1} value={count} onChange={e=>{setCount(Math.max(1,Math.min(20,Math.round(Number(e.target.value)||1))));setAdded(false);}}/></label></div></div>;
 return <div className="order-builder"><div className="order-mode-tabs" role="group" aria-label="Что хотите заказать"><button type="button" className={boardMode?'active':''} aria-pressed={boardMode} onClick={()=>switchMode('board')}><span>1</span>Заказать доску</button><button type="button" className={!boardMode?'active':''} aria-pressed={!boardMode} onClick={()=>switchMode('product')}><span>2</span>Заказать товар</button></div><div className={'configurator '+(compact?'compact':'')}><div className="config-visual"><div className="config-visual-top"><span className="eyebrow">{boardMode?'ДОСКА В ВАШЕМ РАЗМЕРЕ':'ВАШЕ ИЗДЕЛИЕ'}</span></div><div className="config-board-wrap"><BoardPreview p={p} c={c}/></div>
{lengthControls}<div className="config-visual-bottom"><div><h3>{boardMode?'Карельская сосна Кело':p.name}</h3><p>{configuredWidth(p,c)*10} мм ширина · {c.thickness} мм толщина</p></div><span className="stock-dot"><i/>{valid?'Материал доступен':'Проверьте наличие и количество'}</span></div><div className="config-note"><Info size={15}/><p>Схема и текстура — примеры. Природная форма и рисунок каждой реальной доски отличаются.</p></div></div>
 <div className="config-controls"><div className="control-heading"><span className="eyebrow">{boardMode?'ПАРАМЕТРЫ ДОСКИ':'ТОВАРЫ ИЗ КЕЛО'}</span></div>{!boardMode&&<fieldset className="goods-selection"><legend><span>Выберите товар</span></legend><div className="goods-category-tabs" role="group" aria-label="Категории готовых товаров">{categories.filter(cat=>cat.id!=='slabs').map(cat=><button type="button" key={cat.id} aria-pressed={productCategory===cat.id} onClick={()=>{const found=goods.find(g=>g.category===cat.id);setProductCategory(cat.id);if(found)chooseGood(found);}}>{cat.name}</button>)}</div><div className="goods-options">{goods.filter(g=>g.category===productCategory).length?goods.filter(g=>g.category===productCategory).map(g=><button className="goods-choice" type="button" key={g.id} aria-pressed={p.id===g.id} onClick={()=>chooseGood(g)}><img src={productPhotoSet(g)[0].src} alt=""/><span><b>{g.name}</b><small>{g.maxLength*10} × {g.width*10} × {g.thickness} мм</small></span></button>):<p className="fine-print">В этой категории пока нет доступных товаров. Выберите другую категорию.</p>}</div></fieldset>}
 {boardMode&&<fieldset><legend><span>Ширина доски</span></legend><div className="config-dimensions width-only"><label>Ширина · до 400 мм<select value={String(boardWidth*10)} onChange={e=>changeWidth(e.target.value)}>{Array.from(new Set([100,150,200,250,300,350,400,boardWidth*10])).sort((a,b)=>a-b).map(mm=><option key={mm} value={String(mm)}>{mm} мм</option>)}</select></label></div></fieldset>}
 <fieldset className="processing-field"><legend><span>Обработка</span></legend><label className="switch-row"><span>Шлифовка<small>{money(processing.sanding)} / пог. м</small></span><input type="checkbox" className="switch-input" checked={c.sanding} onChange={e=>update({sanding:e.target.checked})}/><MotionSwitch checked={c.sanding}/></label><label className="switch-row"><span>Прямой спил одной стороны<small>{money(processing.cut)} / пог. м</small></span><input type="checkbox" className="switch-input" checked={c.cut} onChange={e=>update({cut:e.target.checked})}/><MotionSwitch checked={c.cut}/></label>{c.cut&&<div className="side-control"><span>Сторона спила</span><div className="segmented"><button type="button" className={c.side==='left'?'active':''} onClick={()=>update({side:'left'})} aria-pressed={c.side==='left'}>Левая</button><button type="button" className={c.side==='right'?'active':''} onClick={()=>update({side:'right'})} aria-pressed={c.side==='right'}>Правая</button></div></div>}<div className="holes-control"><label>Сверление отверстий <small>{money(processing.hole)} / шт.</small></label><div className="segmented">{[0,2,3].map(n=><button type="button" key={n} className={c.holes===n?'active':''} aria-pressed={c.holes===n} onClick={()=>update({holes:n as Configuration['holes']})}>{n===0?'Без отверстий':`${n} отверстия`}</button>)}</div></div></fieldset>
 <fieldset className="extras-field"><legend><span>Дополнить заказ</span></legend>{!boardMode&&isShelf(p)&&<label className="switch-row"><span>Менсолодержатели для полки<small>+ {money(extrasPrice.supports)} / комплект на изделие</small></span><input type="checkbox" className="switch-input" checked={!!c.supports} onChange={e=>update({supports:e.target.checked})}/><MotionSwitch checked={!!c.supports}/></label>}<label className="switch-row"><span>Упаковать в подарочную упаковку<small>+ {money(extrasPrice.giftWrap)} / изделие</small></span><input type="checkbox" className="switch-input" checked={!!c.giftWrap} onChange={e=>update({giftWrap:e.target.checked})}/><MotionSwitch checked={!!c.giftWrap}/></label></fieldset>
 <div className="config-total"><div><span>Стоимость · {count} {boardMode?'досок':'изделий'}</span><strong aria-live="polite">{money(price.total*count)}</strong><small>{count>1?money(price.total)+' за шт. · ':''}Демо-цена · без доставки</small></div><button disabled={!valid} className="btn" type="button" onClick={()=>{if(add(p,c,count))setAdded(true);}}>{added?'Добавлено':'В корзину'}</button></div><details className="price-details"><summary>Из чего складывается цена</summary>{[['Материал',price.material],['Шлифовка',price.sanding],['Прямой спил',price.cut],['Отверстия',price.holes],['Изготовление полки',price.making],['Менсолодержатели',price.supports],['Подарочная упаковка',price.giftWrap]].filter(([,value])=>Number(value)>0).map(([label,value])=><div key={String(label)}><span>{label}{count>1?' × '+count:''}</span><span>{money(Number(value)*count)}</span></div>)}</details></div></div></div>;
}

export function ConstructorPage(){return <main id="main" className="container constructor-page"><Breadcrumb current="Конструктор"/><div className="page-title"><p className="eyebrow">В РАЗМЕР ВАШЕЙ ИДЕИ</p><h1>Ваш замысел. Ваше дерево.</h1><p>Задайте длину и обработку. Мы сохраним всё, за что вы полюбили эту доску.</p></div><DemoNote/><Configurator/><div className="constructor-help"><Ruler size={30}/><div><h3>Доска — от 30 до 150 см</h3><p>Длину задавайте ползунком под изображением, точность — 1 см. При перетаскивании на каждых 10 см ползунок ненадолго задерживается. Полки и другие изделия доступны во вкладке «Заказать товар» с размерами из каталога.</p></div></div></main>;}
export function ProductPage({id}:{id:string}){const {products,add,processing,loading}=useStore();const p=products.find(p=>p.id===id);if(!p)return <main id="main" className="container"><Breadcrumb current="Товар"/><Empty icon={<Package size={38}/>} title={loading?'Загружаем доску…':'Эта доска не найдена'} text="Посмотрите доступную коллекцию."><a className="btn" href="/catalog">В каталог </a></Empty></main>;const c=initialConfig(p);return <main id="main" className="container product-page"><Breadcrumb current={p.name}/><div className="product-detail-grid"><div className="product-detail-image"><PhotoGallery photos={productPhotoSet(p)} label={p.name} variant="detail"/></div><div className="product-detail-info"><p className="eyebrow">{categories.find(c=>c.id===p.category)?.name} / {p.id}</p><h1>{p.name}</h1><p className="stock-dot"><i/>{p.remainingCm>=(p.category==='slabs'?boardLengthLimits.minCm:p.maxLength)?'Доступен в демо-каталоге':'Материал зарезервирован'}</p><p className="product-description">{p.description}</p><dl className="spec-list"><div><dt>Материал</dt><dd>Карельская сосна Кело</dd></div><div><dt>Доступная длина</dt><dd>До {Math.min(p.maxLength,p.remainingCm)} см</dd></div><div><dt>Ширина</dt><dd>{p.width} см</dd></div><div><dt>Толщина</dt><dd>{p.thickness} мм</dd></div><div><dt>Край</dt><dd>Живой, природный</dd></div></dl><div className="detail-price"><b>{money(p.rate)}</b><span>за погонный метр · демо-цена</span></div><a className="btn full" href={'/constructor?board='+p.id}>Настроить заказ </a><button className="btn secondary full" disabled={p.remainingCm<(p.category==='slabs'?boardLengthLimits.minCm:p.maxLength)} onClick={()=>add(p,c)}>Добавить {c.length} см · {money(priceDetails(p,c,processing).total)} </button><DemoNote short/></div></div><div className="product-care"><h2>Природные особенности — часть характера</h2><p>Сучки, трещины, неоднородный оттенок и неровный край делают древесину Кело узнаваемой. Фактическая форма и размеры конкретной доски уточняются по реальным фотографиям перед производством. Для ухода используйте мягкую сухую ткань; избегайте длительного контакта с водой.</p></div></main>;}
export function CartPage(){const {cart,products,processing,quantity,remove}=useStore();const items=cart.map(i=>{const p=products.find(p=>p.id===i.product.id)||i.product;return {...i,product:p,price:priceDetails(p,i.config,processing).total};});const subtotal=items.reduce((s,i)=>s+i.price*i.quantity,0);return <main id="main" className="container cart-page"><Breadcrumb current="Корзина"/><div className="page-title"><p className="eyebrow">ВАШ ВЫБОР</p><h1>Дерево для вашей истории.</h1><p>Все размеры и детали обработки — в одном месте.</p></div>{!items.length?<Empty icon={<ShoppingBag size={42}/>} title="Ваша доска ещё ждёт вас" text="Выберите рисунок, который откликается. Мы подгоним размер под вашу идею."><a className="btn" href="/catalog">Выбрать слэб </a></Empty>:<div className="cart-layout"><div><div className="cart-list">{items.map(i=><article className="cart-item" key={i.key}><a className="cart-item-image" href={'/product/'+i.product.id}><img src={productPhotoSet(i.product)[0].src} alt={i.product.name}/></a><div className="cart-item-detail"><p className="eyebrow">{i.product.id} / {typeNames[i.config.type]}</p><h2>{i.product.name}</h2><ul>{details(i.config,i.product).map(d=><li key={d}>{d}</li>)}</ul><a href={'/constructor?board='+i.product.id} className="small-link">Собрать другой вариант </a><div className="cart-item-actions"><div className="quantity"><button onClick={()=>quantity(i.key,i.quantity-1)} disabled={i.quantity===1} aria-label={'Уменьшить количество '+i.product.name}><Minus size={15}/></button><span>{i.quantity}</span><button onClick={()=>quantity(i.key,i.quantity+1)} aria-label={'Увеличить количество '+i.product.name}><Plus size={15}/></button></div><strong>{money(i.price*i.quantity)}</strong><button className="icon-btn delete" onClick={()=>remove(i.key)} aria-label={'Удалить '+i.product.name}><Trash2 size={18}/></button></div></div></article>)}</div><a className="text-link" href="/catalog">Продолжить выбирать</a></div><aside className="order-summary"><p className="eyebrow">ВАШ ЗАКАЗ</p><h2>Природа — в деталях.</h2><div className="summary-line"><span>Изделия · {items.reduce((s,i)=>s+i.quantity,0)} шт.</span><b>{money(subtotal)}</b></div><div className="summary-line"><span>Доставка</span><span>При оформлении</span></div><div className="summary-total"><span>Итого</span><b>{money(subtotal)}</b></div><a className="btn full" href="/checkout">Оформить заказ </a><p className="fine-print">Демонстрационные цены. Стоимость доставки добавляется при оформлении.</p><div className="summary-assurance"><ShieldCheck size={20}/><span>Все параметры проверим перед изготовлением</span></div></aside></div>}<DemoNote/></main>;}
export function CheckoutPage(){const {cart,products,processing,clear,reload}=useStore();const [deliveryType,setDeliveryType]=useState('delivery'),[payment,setPayment]=useState('online-demo'),[consent,setConsent]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState<{reference:string;subtotal:number;delivery:number|null}|null>(null);const requestId=useRef('');const formRef=useRef<HTMLFormElement>(null);const items=cart.map(i=>{const p=products.find(p=>p.id===i.product.id)||i.product;return {...i,product:p,price:priceDetails(p,i.config,processing).total};});const subtotal=items.reduce((s,i)=>s+i.price*i.quantity,0);const delivery=shipping(items,deliveryType);useEffect(()=>{requestId.current=crypto.randomUUID();},[]);async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setError('');const data=new FormData(e.currentTarget);const phone=String(data.get('phone')||'');if(phone.replace(/\D/g,'').length<10||phone.replace(/\D/g,'').length>15){setError('Укажите телефон: от 10 до 15 цифр с кодом страны.');return;}setBusy(true);try{const res=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:requestId.current,customer:{name:data.get('name'),phone,email:data.get('email')||'',city:data.get('city')||'',address:data.get('address')||'',comment:data.get('comment')||''},deliveryType,payment,consent,items:items.map(i=>({config:i.config,quantity:i.quantity}))})});const result=await res.json() as {error?:string;order:{reference:string;subtotal:number;delivery:number|null}};if(!res.ok)throw new Error(result.error||'Не удалось оформить заказ');setSuccess(result.order);clear();void reload();window.scrollTo({top:0,behavior:'smooth'});}catch(err){setError(err instanceof Error?err.message:'Не удалось оформить заказ. Попробуйте ещё раз.');}finally{setBusy(false);}}
 if(success)return <main id="main" className="container checkout-success"><div className="success-mark"><Check size={44}/></div><p className="eyebrow">ДЕМО-ЗАКАЗ СОХРАНЁН</p><h1>У вашей идеи<br/>теперь есть форма.</h1><p>Заказ <strong>{success.reference}</strong> появился в панели управления.<br/>Материал зарезервирован в демонстрационном каталоге.</p><div className="success-receipt"><div><span>Изделия</span><b>{money(success.subtotal)}</b></div><div><span>Доставка</span><b>{success.delivery===null?'Индивидуальный расчёт':money(success.delivery)}</b></div><div><span>Сумма{success.delivery===null?' без доставки':''}</span><b>{money(success.subtotal+(success.delivery||0))}</b></div></div><p className="success-note"><Info size={18}/>{payment==='online-demo'?'Онлайн-оплата показана как пример. Деньги не списывались.':'Оплата после согласования. В демонстрационной версии платёж не требуется.'} Реальная отправка и связь с менеджером не выполняются.</p><div className="hero-buttons"><a className="btn" href="/catalog">Вернуться в коллекцию </a><a className="btn secondary" href="/admin">Посмотреть заказ </a></div></main>;
 if(!items.length)return <main id="main" className="container"><Empty icon={<ShoppingBag size={38}/>} title="Начнём с красивой доски" text="Добавьте изделие в корзину, чтобы перейти к оформлению."><a className="btn" href="/catalog">В каталог </a></Empty></main>;
 return <main id="main" className="container checkout-page"><Breadcrumb current="Оформление"/><div className="page-title"><p className="eyebrow">ПОСЛЕДНИЕ ДЕТАЛИ</p><h1>Оформление заказа.</h1><p>Это демонстрационная версия. Для проверки используйте вымышленные данные.</p></div><form ref={formRef} onSubmit={submit} className="checkout-grid"><div className="checkout-form"><section><h2><span>01</span> Ваши контакты</h2><div className="form-grid"><label>Имя<input name="name" autoComplete="name" minLength={2} maxLength={100} placeholder="Как к вам обращаться" required/></label><label>Телефон<input name="phone" autoComplete="tel" type="tel" placeholder="+7 (999) 000-00-00" required/></label><label className="full-field">Электронная почта <span className="optional">Необязательно</span><input name="email" type="email" autoComplete="email" placeholder="name@example.ru"/></label></div></section><section><h2><span>02</span> Доставка</h2><div className="delivery-options"><label className={'radio-card '+(deliveryType==='delivery'?'selected':'')}><input type="radio" name="deliveryType" checked={deliveryType==='delivery'} onChange={()=>setDeliveryType('delivery')}/><Truck size={22}/><span><b>Доставка по России</b><small>{delivery===null?'Длинное изделие — индивидуальный расчёт':'Расчёт показан для примера'}</small></span></label><label className={'radio-card '+(deliveryType==='pickup'?'selected':'')}><input type="radio" name="deliveryType" checked={deliveryType==='pickup'} onChange={()=>setDeliveryType('pickup')}/><MapPin size={22}/><span><b>Самовывоз</b><small>Бесплатно · адрес согласуем отдельно</small></span></label></div>{deliveryType==='delivery'&&<div className="form-grid"><label>Город<input name="city" autoComplete="address-level2" placeholder="Москва" maxLength={100} required/></label><label>Адрес<input name="address" autoComplete="street-address" placeholder="Улица, дом, квартира" maxLength={400} required/></label></div>}<p className="fine-print">Яндекс Доставка пока не подключена. {delivery===null?'Для изделий длиннее 250 см доставка не входит в итоговую сумму.':'Стоимость и сроки требуют подтверждения перед отправкой.'}</p></section><section><h2><span>03</span> Оплата</h2><label className={'radio-card '+(payment==='online-demo'?'selected':'')}><input type="radio" name="payment" checked={payment==='online-demo'} onChange={()=>setPayment('online-demo')}/><CreditCard size={23}/><span><b>Онлайн-оплата · пример ЮKassa</b><small>Демонстрационный сценарий, без списания денег</small></span></label><label className={'radio-card '+(payment==='agreement'?'selected':'')}><input type="radio" name="payment" checked={payment==='agreement'} onChange={()=>setPayment('agreement')}/><Package size={23}/><span><b>После согласования</b><small>Параметры, сроки и доставка уточняются отдельно</small></span></label></section><label className="comment-label">Комментарий к заказу <span className="optional">Необязательно</span><textarea name="comment" rows={3} maxLength={1500} placeholder="Расскажите о своём проекте или пожеланиях к обработке"/></label></div><aside className="order-summary checkout-summary"><p className="eyebrow">ВАШ ЗАКАЗ</p><h2>Всё, что вы выбрали.</h2><div className="checkout-items">{items.map(i=><div key={i.key}><img src={productPhotoSet(i.product)[0].src} alt=""/><span><b>{i.product.name}</b><small>{i.config.length} × {configuredWidth(i.product,i.config)} см · {i.config.thickness} мм · {i.quantity} шт.</small>{i.config.supports&&<small>Менсолодержатели · {money(300*i.quantity)}</small>}{i.config.giftWrap&&<small>Подарочная упаковка · {money(300*i.quantity)}</small>}</span><strong>{money(i.price*i.quantity)}</strong></div>)}</div><div className="summary-line"><span>Изделия</span><b>{money(subtotal)}</b></div><div className="summary-line"><span>Доставка</span><span>{delivery===null?'Согласуем отдельно':delivery===0?'Бесплатно':money(delivery)}</span></div><div className="summary-total"><span>{delivery===null?'Без доставки':'Итого'}</span><b>{money(subtotal+(delivery||0))}</b></div><label className="consent"><input type="checkbox" required checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>Согласен на сохранение указанных данных для проверки демо-заказа. Понимаю, что реальная оплата и доставка не выполняются.</span></label>{error&&<p className="form-error" role="alert">{error}</p>}<button className="btn full" type="submit" disabled={busy||!consent}><span>{busy?'Сохраняем заказ…':'Оформить демо-заказ'}</span></button><p className="fine-print">Без ввода данных карты. Деньги не списываются.</p><a className="small-link" href="/cart">Вернуться в корзину</a></aside></form></main>;
}
